function validate([positions]) {
  if (!Array.isArray(positions) || positions.length < 1 || positions.length > 50) return 'positions needs 1 to 50 customers.';
  for (const p of positions) {
    if (!Array.isArray(p) || p.length !== 2) return 'Each position is a pair [x, y].';
    if (!p.every(v => Number.isInteger(v) && v >= 0 && v <= 100)) return 'Each coordinate is a whole number from 0 to 100.';
  }
  return null;
}

