function getMinDistSum(positions) {
  const n = positions.length;
  const totalDistance = (x, y) => {
    let sum = 0;
    for (const [px, py] of positions) {
      sum += Math.hypot(px - x, py - y);
    }
    return sum;
  };

  for (const [ax, ay] of positions) {
    let pullX = 0;
    let pullY = 0;
    let same = 0;
    for (const [px, py] of positions) {
      const d = Math.hypot(px - ax, py - ay);
      if (d === 0) {
        same++;
        continue;
      }
      pullX += (px - ax) / d;
      pullY += (py - ay) / d;
    }
    if (Math.hypot(pullX, pullY) <= same + 1e-9) {
      return totalDistance(ax, ay);
    }
  }

  let x = positions.reduce((sum, p) => sum + p[0], 0) / n;
  let y = positions.reduce((sum, p) => sum + p[1], 0) / n;
  for (let iter = 0; iter < 100000; iter++) {
    let weight = 0;
    let nextX = 0;
    let nextY = 0;
    for (const [px, py] of positions) {
      const d = Math.hypot(px - x, py - y);
      if (d < 1e-12) continue;
      weight += 1 / d;
      nextX += px / d;
      nextY += py / d;
    }
    nextX /= weight;
    nextY /= weight;
    const moved = Math.hypot(nextX - x, nextY - y);
    x = nextX;
    y = nextY;
    if (moved < 1e-9) break;
  }
  return totalDistance(x, y);
}

