function getMinDistSum(positions) {
  // The cost is convex, so its minimum over y is convex in x: nested ternary searches find it.
  const cost = (cx, cy) => {
    let s = 0;
    for (let i = 0; i < positions.length; i++) s += Math.sqrt((positions[i][0] - cx) ** 2 + (positions[i][1] - cy) ** 2);
    return s;
  };
  const bestForX = cx => {
    let lo = 0, hi = 100;
    for (let k = 0; k < 90; k++) {
      const m1 = lo + (hi - lo) / 3, m2 = hi - (hi - lo) / 3;
      if (cost(cx, m1) < cost(cx, m2)) hi = m2; else lo = m1;
    }
    return cost(cx, (lo + hi) / 2);
  };
  let lo = 0, hi = 100;
  for (let k = 0; k < 90; k++) {
    const m1 = lo + (hi - lo) / 3, m2 = hi - (hi - lo) / 3;
    if (bestForX(m1) < bestForX(m2)) hi = m2; else lo = m1;
  }
  return bestForX((lo + hi) / 2);
}

