function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 50;
    const positions = [];
    if (rand() < 0.5) {
      for (let i = 0; i < n; i++) positions.push([int(0, 100), int(0, 100)]);
    } else {
      // A few clusters, so the best point may sit near or on a crowded spot.
      const centres = Array.from({ length: int(2, 4) }, () => [int(0, 100), int(0, 100)]);
      for (let i = 0; i < n; i++) {
        const [cx, cy] = centres[int(0, centres.length - 1)];
        positions.push([Math.min(100, Math.max(0, cx + int(-6, 6))), Math.min(100, Math.max(0, cy + int(-6, 6)))]);
      }
    }
    return [positions];
  }
  const n = int(1, 7);
  const span = [2, 5, 10, 100][int(0, 3)];
  const positions = [];
  const shape = rand();
  for (let i = 0; i < n; i++) {
    if (shape < 0.15) positions.push([int(0, span), 0]);
    else if (shape < 0.3 && i > 0 && rand() < 0.5) positions.push([...positions[int(0, i - 1)]]);
    else positions.push([int(0, span), int(0, span)]);
  }
  return [positions];
}
